def _get_active_blztar() -> str:
    global blztar
    if blztar and blztar.strip():
        return blztar
    for finder in sys.meta_path:
        if (
            hasattr(finder, "b64_string")
            and finder.b64_string
            and finder.b64_string.strip()
            and getattr(finder, "_index", None)
        ):
            return finder.b64_string
    for cand in [
        getattr(sys.modules.get(__name__), "__file__", None),
        sys.argv[0] if sys.argv else None,
    ]:
        if cand:
            try:
                p = Path(cand).resolve()
                if p.is_file():
                    data = p.read_bytes()
                    m = _BLZTAR_RE.search(data)
                    if m:
                        payload = data[m.start("prefix") : m.end("suffix")].decode(
                            "ascii", errors="ignore"
                        )
                        lines = payload.split('"""')
                        if len(lines) >= 2 and len(lines[1].strip()) > 100:
                            return lines[1]
            except Exception:
                pass
    for finder in sys.meta_path:
        if (
            hasattr(finder, "b64_string")
            and finder.b64_string
            and finder.b64_string.strip()
        ):
            return finder.b64_string
    return ""


def get_bundle_version() -> str:
    """Retrieve version string from integrity module or in-memory bundle asset."""
    try:
        from dwimsy.meta.integrity import version

        return version()
    except Exception:
        try:
            ver_text = get_asset_text("dwimsy/_version.py")
            m = re.search(r'__version__\s*=\s*["\']([^"\']+)["\']', ver_text)
            if m:
                return m.group(1)
        except Exception:
            pass
        return "0.1.6.11-dev"


def iter_tar_layers(raw_tar_bytes: bytes) -> List[Dict[str, bytes]]:
    """Parse concatenated TAR layers from raw bytes."""
    if not raw_tar_bytes or all(b == 0 for b in raw_tar_bytes):
        return []

    layers: List[Dict[str, bytes]] = []
    offset = 0
    total = len(raw_tar_bytes)

    while offset < total:
        remaining = raw_tar_bytes[offset:]
        if not remaining or all(b == 0 for b in remaining):
            break

        tar_bio = io.BytesIO(remaining)
        try:
            with tarfile.open(fileobj=tar_bio, mode="r:") as tar:
                files: Dict[str, bytes] = {}
                for m in tar:
                    if m.isfile():
                        norm_name = m.name[2:] if m.name.startswith("./") else m.name
                        if norm_name.startswith("<dwimsy-bundle>/"):
                            norm_name = norm_name[len("<dwimsy-bundle>/") :]
                        f = tar.extractfile(m)
                        files[norm_name] = f.read() if f is not None else b""

                consumed = tar_bio.tell()
                if consumed % 512 != 0:
                    consumed += 512 - (consumed % 512)
                while (
                    offset + consumed < total
                    and raw_tar_bytes[offset + consumed : offset + consumed + 512]
                    == b"\x00" * 512
                ):
                    consumed += 512

                offset += consumed
                layers.append(files)
        except Exception:
            break

    return layers


def materialize_stream0_assets_with_removals(
    b64_string: Optional[str] = None,
) -> Tuple[Dict[str, bytes], Set[str]]:
    """Materialize primary assets and retain the net removal-marker paths."""
    payload = (
        b64_string
        if (b64_string is not None and b64_string.strip())
        else _get_active_blztar()
    )
    raw_bytes = (
        base64.b64decode(b"".join(payload.encode("ascii").split())) if payload else b""
    )
    if not raw_bytes:
        return {}, set()
    decomp = lzma.LZMADecompressor()
    try:
        data = decomp.decompress(raw_bytes)
    except lzma.LZMAError:
        return {}, set()
    if not data:
        return {}, set()
    layers = iter_tar_layers(data)
    if not layers:
        return {}, set()

    state: Dict[str, bytes] = dict(layers[0])
    removals: Set[str] = set()
    for lyr in layers[1:]:
        v_data = lyr.get("dwimsy/_version.py") or lyr.get("_version.py")
        code_hash = ""
        if v_data:
            m = re.search(
                r'__code_hash__\s*=\s*["\']([^"\']*)["\']',
                v_data.decode("utf-8", errors="ignore"),
            )
            if m:
                code_hash = m.group(1).strip()
        if code_hash:
            break
        for fname, fdata in lyr.items():
            p = Path(fname)
            if p.name.startswith(".wh."):
                real_name = (
                    (p.parent / p.name[4:]).as_posix()
                    if str(p.parent) != "."
                    else p.name[4:]
                )
                state.pop(real_name, None)
                removals.add(real_name)
            else:
                state[fname] = fdata
                removals.discard(fname)
    return state, removals


def materialize_stream0_assets(b64_string: Optional[str] = None) -> Dict[str, bytes]:
    """Materialize primary stream assets, applying open delta removal markers."""
    state, _removals = materialize_stream0_assets_with_removals(b64_string)
    return state


def _open_bundle_tar(b64_string: Optional[str] = None) -> tarfile.TarFile:
    """Open stream 0 tar archive representation."""
    payload = (
        b64_string
        if (b64_string is not None and b64_string.strip())
        else _get_active_blztar()
    )
    raw_bytes = (
        base64.b64decode(b"".join(payload.encode("ascii").split())) if payload else b""
    )
    if not raw_bytes:
        return tarfile.open(fileobj=io.BytesIO(b"\x00" * 1024), mode="r:")
    decomp = lzma.LZMADecompressor()
    try:
        data = decomp.decompress(raw_bytes)
    except lzma.LZMAError:
        return tarfile.open(fileobj=io.BytesIO(b"\x00" * 1024), mode="r:")
    if not data:
        return tarfile.open(fileobj=io.BytesIO(b"\x00" * 1024), mode="r:")
    return tarfile.open(fileobj=io.BytesIO(data), mode="r:*")


def list_assets(b64_string: Optional[str] = None) -> List[str]:
    """List all file paths present in the active stream 0 bundle archive."""
    return sorted(materialize_stream0_assets(b64_string).keys())


def get_asset(filename: str, b64_string: Optional[str] = None) -> bytes:
    """Extract a single file from the in-memory bundle payload as raw bytes."""
    norm_target = Path(filename).as_posix()
    if norm_target.startswith("<dwimsy-bundle>/"):
        norm_target = norm_target[len("<dwimsy-bundle>/") :]
    assets = materialize_stream0_assets(b64_string)
    if norm_target in assets:
        return assets[norm_target]
    raise FileNotFoundError(f"Asset '{filename}' not found in bundle payload")


def get_asset_text(
    filename: str,
    b64_string: Optional[str] = None,
    encoding: str = "utf-8",
) -> str:
    """Extract a single file from the in-memory bundle payload as decoded text."""
    return get_asset(filename, b64_string=b64_string).decode(encoding)


def safe_unbundle(
    b64_string: Optional[str] = None,
    output_dir: str | Path = ".",
    with_deps: bool = False,
    force: bool = False,
    dry_run: bool = False,
    quiet: bool = False,
    stdout=None,
    stderr=None,
    target_version: Optional[str] = None,
    verbose: bool = False,
) -> None:
    """Smart destination verification and delta unpacking engine adhering to Spec Section2.1, Section3, Section3.1."""
    stdout = stdout or sys.stdout
    stderr = stderr or sys.stderr
    out_path = Path(output_dir).resolve()

    effective_b64 = (
        b64_string if (b64_string and b64_string.strip()) else _get_active_blztar()
    )
    from dwimsy.meta.versions import VersionSpace

    vspace = (
        VersionSpace.from_blztar(effective_b64) if effective_b64 else VersionSpace()
    )
    target_version_tag: Optional[str] = None
    target_hash: Optional[str] = None
    target_timestamp: Optional[str] = None

    if target_version is not None:
        res_v = vspace.resolve_version_ref(target_version)
        if res_v is not None:
            s_t, ord_t, ref_t = res_v
            assets = s_t.materialize_layer_state(ord_t)
            removals = set()
            target_version_tag = ref_t.tag
            target_hash = ref_t.content_hash
            target_timestamp = vspace.get_layer_timestamp(s_t.layers[ord_t])
        else:
            assets, removals = materialize_stream0_assets_with_removals(effective_b64)
    else:
        assets, removals = materialize_stream0_assets_with_removals(effective_b64)
        if vspace.streams and vspace.streams[0].layers:
            head_v = vspace.streams[0].get_head_version()
            if head_v:
                target_version_tag = head_v.tag
                target_hash = head_v.content_hash
                target_timestamp = vspace.get_layer_timestamp(
                    vspace.streams[0].layers[head_v.ordinal]
                )

    from dwimsy.meta.versions import portable_path_error

    invalid_paths = [(name, portable_path_error(name)) for name in assets]
    invalid_paths = [(name, err) for name, err in invalid_paths if err]
    if invalid_paths:
        details = "\n".join(err for _name, err in invalid_paths)
        raise ValueError("Cannot extract non-portable paths:\n" + details)

    # 1. Type Collision Guard (Spec Section3.1)
    if out_path.exists() and not force:
        for norm_name in assets:
            if not with_deps and (norm_name == "deps" or norm_name.startswith("deps/")):
                continue
            dest_file = out_path / norm_name
            if dest_file.is_dir():
                raise RuntimeError(
                    f"Type collision: target file '{norm_name}' exists as a directory on disk. Use --force to override."
                )
            for parent_part in dest_file.parents:
                if parent_part == out_path:
                    break
                if parent_part.is_file() or parent_part.is_symlink():
                    kind = "symlink" if parent_part.is_symlink() else "file"
                    raise RuntimeError(
                        f"Type collision: directory component '{parent_part.relative_to(out_path)}' exists as a {kind} on disk. Use --force to override."
                    )

    # 2. Check existing on-disk modifications and branches (Surviving State Verification, Spec Section3.1)
    previous_version_tag: Optional[str] = None
    if target_version_tag is None:
        target_v_data = assets.get("dwimsy/_version.py") or assets.get("_version.py")
        if target_v_data:
            m = re.search(
                r'__version__\s*=\s*["\x27]([^"\x27]+)["\x27]',
                target_v_data.decode("utf-8", errors="ignore"),
            )
            if m:
                target_version_tag = m.group(1).strip()

    def _norm_file_bytes(k: str, b: bytes) -> bytes:
        if k == "dwimsy/meta/unbundle.py":
            try:
                return elide_blztar_bytes(b)
            except Exception:
                pass
        return b

    if out_path.is_dir() and any(out_path.iterdir()):
        disk_files: Dict[str, bytes] = {}
        for p in out_path.rglob("*"):
            if p.is_file():
                rel = p.relative_to(out_path).as_posix()
                if "__pycache__" not in rel and not rel.endswith(".pyc"):
                    try:
                        disk_files[rel] = p.read_bytes()
                    except OSError:
                        pass

        clean_disk = {
            k: _norm_file_bytes(k, v)
            for k, v in disk_files.items()
            if with_deps or not (k == "deps" or k.startswith("deps/"))
        }
        clean_assets = {
            k: _norm_file_bytes(k, v)
            for k, v in assets.items()
            if with_deps or not (k == "deps" or k.startswith("deps/"))
        }

        is_identical_subset = bool(clean_disk) and all(
            k in clean_assets and clean_disk[k] == clean_assets[k] for k in clean_disk
        )

        if is_identical_subset:
            previous_version_tag = target_version_tag
        else:
            matching_ver_tag = None
            for s in vspace.streams:
                for v in s.get_versions():
                    st = s.materialize_layer_state(v.ordinal)
                    clean_st = {
                        k: _norm_file_bytes(k, v_b)
                        for k, v_b in st.items()
                        if with_deps or not (k == "deps" or k.startswith("deps/"))
                    }
                    if clean_disk == clean_st:
                        matching_ver_tag = v.tag
                        break
                if matching_ver_tag is not None:
                    break

            if matching_ver_tag is not None:
                previous_version_tag = matching_ver_tag
                if not force and (
                    "dwimsy/meta/unbundle.py" in assets
                    or (out_path / "dwimsy" / "meta" / "unbundle.py").exists()
                ):
                    if previous_version_tag != target_version_tag:
                        res_prev = vspace.resolve_version_ref(previous_version_tag)
                        if res_prev is None:
                            msg = (
                                f"error: unbundling would overwrite 'dwimsy/meta/unbundle.py' but the new bundle payload "
                                f"does not contain previous on-disk version '{previous_version_tag}'. "
                                f"Use --force / -f to overwrite."
                            )
                            raise RuntimeError(msg)
            else:
                if not force:
                    msg = (
                        f"error: unbundling to '{output_dir}' would overwrite modified on-disk state.\n"
                        f"To protect uncommitted work, specify one of the following flags:\n"
                        f"  --version-include-primary={output_dir}  (preserve local modifications in primary stream)\n"
                        f"  --version-include-alt={output_dir}      (preserve alternate branches)\n"
                        f"  --version-include={output_dir}          (preserve both modifications and branches)\n"
                        f"Or use --force / -f to forcefully overwrite destination."
                    )
                    raise RuntimeError(msg)

    # 3. Compute manifest actions and perform extraction
    manifest_lines: List[str] = []
    import datetime

    now_ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    if not dry_run:
        out_path.mkdir(parents=True, exist_ok=True)

    for norm_name, content in sorted(assets.items()):
        if norm_name.startswith("<dwimsy-bundle>/"):
            norm_name = norm_name[len("<dwimsy-bundle>/") :]
        if not with_deps and (norm_name == "deps" or norm_name.startswith("deps/")):
            continue

        dest_file = out_path / norm_name
        file_size = len(content)
        size_str = f"{file_size:>8} B"

        if not dest_file.exists():
            action_char = "+"
            annotation = ""
        else:
            existing_bytes = dest_file.read_bytes() if dest_file.is_file() else b""
            if existing_bytes == content:
                if not force:
                    continue
                action_char = "="
                annotation = " [IDENTICAL]"
            else:
                action_char = "~"
                annotation = " [REPLACED]" if force else " [UPDATED]"

        manifest_lines.append(
            f"[{action_char}] [F] {size_str}  {now_ts}  {norm_name}{annotation}"
        )

        if not dry_run:
            dest_file.parent.mkdir(parents=True, exist_ok=True)
            if dest_file.exists() or dest_file.is_symlink():
                dest_file.unlink()
            dest_file.write_bytes(content)
            if dest_file.suffix == ".py" and content.startswith(b"#!"):
                try:
                    dest_file.chmod(dest_file.stat().st_mode | 0o111 | 0o755)
                except (OSError, PermissionError):
                    pass

    for norm_name in sorted(removals):
        if norm_name.startswith("<dwimsy-bundle>/"):
            norm_name = norm_name[len("<dwimsy-bundle>/") :]
        if not with_deps and (norm_name == "deps" or norm_name.startswith("deps/")):
            continue
        dest_file = out_path / norm_name
        if not dest_file.exists() and not dest_file.is_symlink():
            continue
        file_size = dest_file.stat().st_size if dest_file.is_file() else 0
        manifest_lines.append(
            f"[-] [F] {file_size:>8} B  {now_ts}  {norm_name} [REMOVED]"
        )
        if not dry_run:
            if dest_file.is_file() or dest_file.is_symlink():
                dest_file.unlink()
            elif dest_file.is_dir():
                try:
                    dest_file.rmdir()
                except OSError:
                    pass

    if not dry_run:
        target_unbundle = out_path / "dwimsy" / "meta" / "unbundle.py"
        target_unbundle.parent.mkdir(parents=True, exist_ok=True)
        try:
            template = elide_blztar_bytes(Path(__file__).read_bytes())
            target_unbundle.write_bytes(inject_blztar_bytes(template, effective_b64))
            try:
                target_unbundle.chmod(0o755)
            except OSError:
                pass
            try:
                with _open_bundle_tar(effective_b64) as source_tar:
                    try:
                        member = source_tar.getmember("dwimsy/meta/unbundle.py")
                    except KeyError:
                        member = source_tar.getmember("./dwimsy/meta/unbundle.py")
                    os.utime(target_unbundle, (member.mtime, member.mtime))
            except (KeyError, OSError, tarfile.TarError):
                pass
        except Exception:
            pass

    if not quiet:
        if manifest_lines:
            for line in manifest_lines:
                print(line, file=stdout)
        if dry_run:
            print(
                f"repeat command without --dry-run to commit changes to {output_dir}",
                file=stdout,
            )
        else:
            from dwimsy.meta.integrity import version_banner

            banner = version_banner(
                prog="dwimsy",
                verbose=verbose,
                version_tag=target_version_tag,
                timestamp=target_timestamp,
                content_hash=target_hash,
            )
            print(f"Successfully extracted {banner} to {output_dir}", file=stdout)
            if (
                previous_version_tag is not None
                and target_version_tag is not None
                and previous_version_tag != target_version_tag
            ):
                unb_rel = (
                    (out_path / "dwimsy" / "meta" / "unbundle.py")
                    .relative_to(out_path)
                    .as_posix()
                    if (out_path / "dwimsy" / "meta" / "unbundle.py").exists()
                    else "dwimsy/meta/unbundle.py"
                )
                out_arg = "." if str(output_dir) == "." else str(output_dir)
                print(
                    f"To return to previous version '{previous_version_tag}', run:\n"
                    f"  python3 {unb_rel} --version={previous_version_tag} {out_arg}",
                    file=stdout,
                )


def extract_b64_lzma_tar(
    b64_string: Optional[str] = None,
    output_dir: str | Path = ".",
    self_path: Optional[str | Path] = None,
    with_deps: bool = False,
) -> None:
    """Extract base64 bundle archive forwarding to safe_unbundle."""
    safe_unbundle(
        b64_string=b64_string,
        output_dir=output_dir,
        with_deps=with_deps,
        force=True,
        quiet=True,
    )
    target_unbundle = Path(output_dir).resolve() / "dwimsy" / "meta" / "unbundle.py"
    if target_unbundle.is_file():
        try:
            with _open_bundle_tar(b64_string) as source_tar:
                member = source_tar.getmember("dwimsy/meta/unbundle.py")
                os.utime(target_unbundle, (member.mtime, member.mtime))
        except (KeyError, OSError, tarfile.TarError):
            pass


def extract_deps(output_dir: str | Path, b64_string: Optional[str] = None) -> List[str]:
    """Extract frozen dependencies into output_dir/deps."""
    out_path = Path(output_dir).resolve()
    deps_dir = out_path / "deps"
    deps_dir.mkdir(parents=True, exist_ok=True)
    extracted: List[str] = []

    assets = materialize_stream0_assets(b64_string)
    for norm_name, content in assets.items():
        if norm_name.startswith("<dwimsy-bundle>/"):
            norm_name = norm_name[len("<dwimsy-bundle>/") :]
        if norm_name.startswith("deps/"):
            dest_file = out_path / norm_name
            dest_file.parent.mkdir(parents=True, exist_ok=True)
            dest_file.write_bytes(content)
            extracted.append(norm_name)
    return extracted


class BundleFinder(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    """Imports modules directly from in-memory blztar with shadow fallback for deps/."""

    def __init__(
        self,
        b64_string: str,
        self_mod: Optional[types.ModuleType] = None,
        on_disk_root: Optional[Path] = None,
    ):
        self.b64_string = b64_string
        self.self_mod = self_mod
        self.on_disk_root = on_disk_root
        raw_assets = materialize_stream0_assets(b64_string)
        self._index: dict[str, bytes] = {}
        for k, v in raw_assets.items():
            clean_k = (
                k[len("<dwimsy-bundle>/") :] if k.startswith("<dwimsy-bundle>/") else k
            )
            self._index[clean_k] = v

        self.declared_deps: Set[str] = set()
        gitmodules_data = self._index.get(".gitmodules")
        if self.on_disk_root and (self.on_disk_root / ".gitmodules").is_file():
            try:
                gitmodules_data = (self.on_disk_root / ".gitmodules").read_bytes()
            except Exception:
                pass
        if gitmodules_data:
            text = gitmodules_data.decode("utf-8", errors="ignore")
            for line in text.splitlines():
                m = re.match(r"\s*path\s*=\s*deps/([A-Za-z0-9_.-]+)", line)
                if m:
                    self.declared_deps.add(m.group(1))

    def is_in_git_checkout(self) -> bool:
        if self.on_disk_root:
            return (self.on_disk_root / ".git").exists() or (
                self.on_disk_root / ".gitmodules"
            ).exists()
        return False

    def find_spec(self, fullname: str, path=None, target=None):
        if fullname == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return importlib.machinery.ModuleSpec(
                name=fullname,
                loader=self,
                origin="<dwimsy-bundle>/dwimsy/meta/unbundle.py",
                is_package=False,
            )

        if fullname.startswith("deps.") or fullname == "deps":
            parts = fullname.split(".")
            if len(parts) > 1:
                dep_name = parts[1]
                if (
                    self.on_disk_root
                    and (self.on_disk_root / "deps" / dep_name).exists()
                ):
                    return None
                if self.is_in_git_checkout() and dep_name not in self.declared_deps:
                    return None

        if not (
            fullname == "dwimsy"
            or fullname.startswith("dwimsy.")
            or fullname == "deps"
            or fullname.startswith("deps.")
        ):
            return None

        # A BundleFinder attached to a real checkout is a fallback provider,
        # not a permanent shadow of the live source tree.  Let normal import
        # machinery use an on-disk module when that module exists; this also
        # prevents a finder left by an earlier in-process dispatch from
        # contaminating subsequent ordinary CLI invocations.
        if self.on_disk_root is not None and fullname != "dwimsy.meta.unbundle":
            rel_base_live = fullname.replace(".", "/")
            if (self.on_disk_root / f"{rel_base_live}.py").is_file() or (
                self.on_disk_root / rel_base_live / "__init__.py"
            ).is_file():
                return None

        rel_base = fullname.replace(".", "/")
        pkg_path = f"{rel_base}/__init__.py"
        mod_path = f"{rel_base}.py"
        dep_pkg_path = f"deps/{rel_base}/__init__.py"
        dep_mod_path = f"deps/{rel_base}.py"

        for candidate, is_pkg in [
            (pkg_path, True),
            (mod_path, False),
            (dep_pkg_path, True),
            (dep_mod_path, False),
        ]:
            if candidate in self._index:
                spec = importlib.machinery.ModuleSpec(
                    name=fullname,
                    loader=self,
                    origin=f"<dwimsy-bundle>/{candidate}",
                    is_package=is_pkg,
                )
                if is_pkg:
                    spec.submodule_search_locations = [f"<dwimsy-bundle>/{rel_base}"]
                return spec
        return None

    def create_module(self, spec):
        if spec.name == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return self.self_mod
        return None

    def exec_module(self, module: types.ModuleType):
        if module.__spec__.name == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return
        origin = module.__spec__.origin
        if not origin or not origin.startswith("<dwimsy-bundle>/"):
            raise ImportError(f"Cannot execute module from origin {origin}")

        path = origin.removeprefix("<dwimsy-bundle>/")
        source = self._index.get(path)
        if source is None:
            raise ImportError(f"Missing bundled source for {path}")

        code = compile(source, origin, "exec")
        module.__file__ = origin
        exec(code, module.__dict__)


def detect_self_location(
    argv0_override: Optional[str] = None,
) -> Tuple[bool, Optional[Path]]:
    """Determine if executing inside a real git checkout with sibling corroboration."""
    if argv0_override:
        candidates = [Path(argv0_override)]
    else:
        candidates = []
        try:
            candidates.append(Path(__file__))
        except NameError:
            pass
        if sys.argv and sys.argv[0]:
            candidates.append(Path(sys.argv[0]))

    for c in candidates:
        try:
            p = c.resolve()
            if p.name in ("unbundle.py", "unbundle.pyc") or (
                p.name.startswith("unbundle.cpython-") and p.name.endswith(".pyc")
            ):
                if (
                    len(p.parts) >= 3
                    and p.parts[-3] == "dwimsy"
                    and p.parts[-2] == "meta"
                ):
                    repo_root = p.parents[2]
                    if (repo_root / "dwimsy" / "_version.py").is_file() and (
                        repo_root / "tests"
                    ).is_dir():
                        return (True, repo_root)
        except Exception:
            pass
    return (False, None)


def get_invocation_path(
    argv0: Optional[str] = None, fallback_file: Optional[str] = None
) -> str:
    """Determines the normalized, un-dereferenced invocation path preserving symlink identity."""
    raw = (
        argv0
        if argv0 is not None
        else (sys.argv[0] if sys.argv and sys.argv[0] else None)
    )
    if not raw or raw in ("-c", "-m"):
        raw = (
            fallback_file
            or getattr(sys.modules.get("__main__"), "__file__", None)
            or __file__
        )
        while raw and not os.path.exists(raw):
            parent = os.path.dirname(raw)
            if parent == raw:
                break
            raw = parent

    sep = os.sep
    altsep = os.altsep
    has_sep = (sep in raw) or (altsep is not None and altsep in raw)
    if not has_sep:
        found = shutil.which(raw)
        if found:
            raw = found

    return os.path.normpath(os.path.abspath(raw))


def apply_arg_overrides(
    initial_path: str, argv: Sequence[str]
) -> Tuple[str, List[str]]:
    """Processes chained '-a NAME' / '--argv0 NAME' flags from argv with relative directory resolution."""
    current_path = initial_path
    remaining_argv: List[str] = []
    i = 0

    while i < len(argv):
        arg = argv[i]
        arg_lower = arg.lower()
        override = None

        if arg_lower in ("-a", "--argv0") and i + 1 < len(argv):
            override = argv[i + 1]
            i += 2
        elif arg_lower.startswith("-a="):
            override = arg[3:]
            i += 1
        elif arg_lower.startswith("--argv0="):
            override = arg[8:]
            i += 1
        else:
            remaining_argv.append(arg)
            i += 1
            continue

        if os.path.isabs(override):
            current_path = os.path.normpath(override)
        else:
            parent_dir = os.path.dirname(current_path)
            current_path = os.path.normpath(os.path.join(parent_dir, override))

    return current_path, remaining_argv


def parse_early_pipeline_flags(
    args: List[str], initial_argv0: Optional[str] = None
) -> Tuple[Dict[str, Any], List[str]]:
    """Universal Tier 1 bootstrap scanner implementing Spec v8.6 state machine."""
    import unicodedata

    this_mod = sys.modules.get("dwimsy.meta.unbundle") or sys.modules.get("__main__")
    if this_mod is not None and "dwimsy.meta.unbundle" not in sys.modules:
        sys.modules["dwimsy.meta.unbundle"] = this_mod
    raw_b64 = _get_active_blztar()
    if not any(isinstance(finder, BundleFinder) for finder in sys.meta_path):
        if raw_b64:
            sys.meta_path.insert(0, BundleFinder(raw_b64, self_mod=this_mod))
    from dwimsy.meta.versions import VersionSpace

    vspace = VersionSpace.from_blztar(raw_b64) if raw_b64 else VersionSpace()
    current_argv0 = initial_argv0 or (
        sys.argv[0] if sys.argv and sys.argv[0] else "dwimsy"
    )
    argv0_overridden = False

    active_selection = vspace.resolve_selection("primary")
    effective_version_str = (
        active_selection.first.version.tag
        if active_selection and active_selection.first
        else get_bundle_version()
    )

    operations: List[Tuple[str, Any]] = []
    short_v_count = 0
    explicit_verbose_count = 0
    explicit_version_requested = False
    version_snapshots: List[str] = []
    test_mode = False
    test_pattern = None
    early_exit = None
    version_list_snapshot = None
    remaining_args: List[str] = []

    # Resolve version-list format and verbosity from full invocation
    has_version_list = any(
        a.lower() == "--version-list" or a.lower().startswith("--version-list=")
        for a in args
    )
    is_full = any(
        a.lower() in ("--version-list=full", "--version-list=long") for a in args
    )
    is_short = any(
        a.lower() in ("--version-list=short", "--version-list=compact") for a in args
    )
    has_v_flag = any(
        a.startswith("-") and not a.startswith("--") and any(c in "vV" for c in a[1:])
        for a in args
    )
    has_verbose_flag = any(a.lower() == "--verbose" for a in args)
    version_list_verbose = (has_verbose_flag or has_v_flag or is_full) and not is_short

    i = 0
    while i < len(args):
        raw_arg = args[i]
        norm_arg = unicodedata.normalize("NFKC", raw_arg)

        if "=" in norm_arg or "\uff1d" in raw_arg:
            if "=" in raw_arg:
                raw_k, raw_v = raw_arg.split("=", 1)
            else:
                raw_k, raw_v = raw_arg.split("\uff1d", 1)
            opt_key = unicodedata.normalize("NFKC", raw_k).lower()
            opt_val = raw_v
            has_val = True
        else:
            opt_key = norm_arg.lower()
            opt_val = None
            has_val = False

        # 1. -a / --argv0
        if opt_key in ("-a", "--argv0"):
            if has_val:
                val = opt_val
                i += 1
            elif i + 1 < len(args):
                val = args[i + 1]
                i += 2
            else:
                val = ""
                i += 1
            if os.path.isabs(val):
                current_argv0 = os.path.normpath(val)
            else:
                parent_dir = os.path.dirname(current_argv0) if current_argv0 else "."
                current_argv0 = os.path.normpath(os.path.join(parent_dir, val))
            argv0_overridden = True
            operations.append(("argv0", val))
            remaining_args = []
            continue

        # 2. --version-include*
        if opt_key == "--version-include-primary" and has_val:
            val = opt_val
            vspace.include_source(val, stream_filter="primary")
            operations.append(("include-primary", val))
            i += 1
            continue
        m_inc_altN = re.match(r"^--version-include-alt(\d+)$", opt_key)
        if m_inc_altN and has_val:
            alt_idx = int(m_inc_altN.group(1))
            val = opt_val
            vspace.include_source(val, stream_filter=f"alt{alt_idx}")
            operations.append(("include-altN", (alt_idx, val)))
            i += 1
            continue
        if opt_key == "--version-include-alt" and has_val:
            val = opt_val
            vspace.include_source(val, stream_filter="alt")
            operations.append(("include-alt", val))
            i += 1
            continue
        if opt_key == "--version-include" and has_val:
            val = opt_val
            vspace.include_source(val)
            operations.append(("include", val))
            i += 1
            continue

        # 3. --version-restrict-to
        if opt_key == "--version-restrict-to" and has_val:
            val = opt_val
            vspace.restrict_to(val)
            operations.append(("restrict_to", val))
            i += 1
            continue

        # 4. --version-prune
        if opt_key == "--version-prune" and has_val:
            val = opt_val
            vspace.prune(val)
            operations.append(("prune", val))
            i += 1
            continue

        # 5. --version-splice
        if opt_key == "--version-splice" and has_val:
            val = opt_val
            vspace.splice(val)
            operations.append(("splice", val))
            i += 1
            continue

        # 6. --version-alt
        if opt_key == "--version-alt":
            branch_tag = opt_val if has_val else None
            if branch_tag is None or branch_tag.lower() == "selected":
                vspace.branch_selection(active_selection)
            else:
                selection = vspace.resolve_selection(branch_tag)
                if not selection:
                    raise ValueError(
                        f"Version selector '{branch_tag}' could not be resolved."
                    )
                vspace.branch_selection(selection)
            operations.append(("alt", branch_tag))
            i += 1
            continue

        # 7. --version=TAG
        if opt_key == "--version" and has_val:
            val = opt_val
            if val.lower() == "selected":
                pass
            else:
                active_selection = vspace.resolve_selection(val)
                if not active_selection and val.lower() != "unbundled":
                    raise ValueError(f"Version selector '{val}' could not be resolved.")
            if active_selection and active_selection.first:
                effective_version_str = (
                    active_selection.first.version.tag
                    if not active_selection.is_multi
                    else "alt"
                )
            else:
                effective_version_str = val
            operations.append(("version", val))
            i += 1
            continue

        # 8. --version-list
        if opt_key == "--version-list":
            if version_list_snapshot is None:
                is_chk, r_root = detect_self_location(current_argv0)
                version_list_snapshot = vspace.format_list_versions(
                    on_disk_root=r_root if is_chk else None,
                    selected=active_selection,
                    verbose=version_list_verbose,
                )
                if early_exit is None:
                    early_exit = "version-list"
            operations.append(("version-list", None))
            i += 1
            continue

        # 9. --version-help
        if opt_key == "--version-help":
            if early_exit is None:
                early_exit = "version-help"
            operations.append(("version-help", None))
            i += 1
            continue

        # 10. Bare --version or -V
        if (opt_key == "--version" and not has_val) or (
            opt_key == "-v" and norm_arg == "-V"
        ):
            explicit_version_requested = True
            version_snapshots.append(effective_version_str)
            operations.append(("version_query", effective_version_str))
            i += 1
            continue

        # 11. Short -v flags (polymorphic state machine)
        if (
            norm_arg.startswith("-")
            and not norm_arg.startswith("--")
            and len(norm_arg) > 1
            and all(c in "vV" for c in norm_arg[1:])
        ):
            n = len(norm_arg) - 1
            short_v_count += n
            for _ in range(n):
                version_snapshots.append(effective_version_str)
            operations.append(("short_v", (n, effective_version_str)))
            i += 1
            continue

        # 12. Explicit --verbose
        if opt_key == "--verbose":
            explicit_verbose_count += 1
            i += 1
            continue

        # 13. Test mode flags: -t, -T, --test, --test=PATTERN
        if opt_key in ("-t", "-T", "--test"):
            test_mode = True
            if has_val:
                test_pattern = opt_val
            elif (
                i + 1 < len(args)
                and not args[i + 1].startswith("-")
                and args[i + 1] not in TOP_COMMANDS
                and args[i + 1] not in APPLET_VERBS
            ):
                test_pattern = args[i + 1]
                i += 1
            i += 1
            continue

        # 14. Help flags: -h, -?, /?, --help
        if opt_key in ("-h", "-?", "/?", "--help"):
            if early_exit is None:
                early_exit = "help"
            remaining_args.append("-h")
            i += 1
            continue
        if opt_key == "--help-all":
            if early_exit is None:
                early_exit = "help-all"
            remaining_args.append("--help-all")
            i += 1
            continue

        remaining_args.append(raw_arg)
        i += 1

    print_version = False
    if not has_version_list and not early_exit and not test_mode:
        if short_v_count == 1 and explicit_verbose_count == 0:
            print_version = True
        elif explicit_version_requested:
            print_version = True

    verbosity = (
        max(0, short_v_count - 1) + explicit_verbose_count
        if not test_mode
        else (short_v_count + explicit_verbose_count)
    )

    pipeline: Dict[str, Any] = {
        "argv0": current_argv0,
        "argv0_overridden": argv0_overridden,
        "operations": operations,
        "vspace": vspace,
        "selected_ref": active_selection,
        "effective_version": effective_version_str,
        "version_snapshots": version_snapshots,
        "short_v_count": short_v_count,
        "explicit_verbose_count": explicit_verbose_count,
        "verbosity": verbosity,
        "test_mode": test_mode,
        "test_pattern": test_pattern,
        "print_version": print_version,
        "early_exit": early_exit,
        "version_list_snapshot": version_list_snapshot,
        "version_list_verbose": version_list_verbose,
        "include": [val for op, val in operations if op.startswith("include")],
        "restrict_to": next(
            (val for op, val in reversed(operations) if op == "restrict_to"), None
        ),
        "prune": next((val for op, val in reversed(operations) if op == "prune"), None),
        "splice": next(
            (val for op, val in reversed(operations) if op == "splice"), None
        ),
        "alt": next(
            ((True, val) for op, val in reversed(operations) if op == "alt"),
            (False, None),
        ),
        "version": next(
            (val for op, val in reversed(operations) if op == "version"), None
        ),
        "list_versions": any(op == "version-list" for op, _ in operations),
        "version_help": any(op == "version-help" for op, _ in operations),
    }

    return pipeline, remaining_args


APPLET_VERBS = {"t882wav", "wav2t88"}
META_SUBCOMMANDS = {
    "bundle",
    "unbundle",
    "diff",
    "integrity",
    "lint",
    "version-bump",
    "fetch-deps",
    "bundle-fixtures",
}
TOP_COMMANDS = {
    "convert",
    "inspect",
    "split",
    "join",
    "tests",
    "readme",
    "license",
    "changelog",
    "help",
    "charset",
    "extract",
    "package",
    "bridge",
    "archive",
    "recover",
}


def _invocation_tokens(value: str) -> List[str]:
    text = os.fspath(value).strip()
    text = re.sub(r"[\s_\-/\\]+", "/", text)
    parts = [p for p in text.split("/") if p]
    if not parts:
        return []
    last = parts[-1]
    for ext in (".py", ".pyz", ".pyc", ".exe"):
        if last.lower().endswith(ext):
            last = last[: -len(ext)]
            break
    parts[-1] = last
    if len(parts) >= 2 and re.fullmatch(
        r"v?\d+(?:[.]\d+){1,3}(?:[-+][0-9A-Za-z._+-]+)?", parts[-1], re.I
    ):
        parts.pop()
    return [p.lower() for p in parts if p]


def _command_from_tokens(tokens: List[str]) -> List[str]:
    for i in range(len(tokens)):
        tail = tokens[i:]
        if tail and tail[0] == "dwimsy":
            tail = tail[1:]
        if len(tail) == 1 and tail[0] == "meta":
            return ["meta"]
        if len(tail) >= 2 and tail[0] == "meta" and tail[1] in META_SUBCOMMANDS:
            return ["meta", tail[1]]
        if len(tail) == 1 and tail[0] in APPLET_VERBS:
            return [tail[0]]
        if len(tail) == 1 and tail[0] in TOP_COMMANDS:
            return [tail[0]]
    return []


def resolve_argv0_command(argv0: str) -> List[str]:
    return _command_from_tokens(_invocation_tokens(argv0))


def resolve_multicall_verb(argv0: str) -> Optional[str]:
    cmd = resolve_argv0_command(argv0)
    return cmd[0] if len(cmd) == 1 and cmd[0] in APPLET_VERBS else None


UNBUNDLE_PROG_PATTERN = re.compile(
    r"^(?:.*[/\\])?(?:(?:dwimsy[.\-_/ ])?(?:meta[.\-_/ ])?)?unbundle(?:\.py|\.pyz|\.pyc)?(?: |$)",
    re.IGNORECASE,
)


def is_unbundle_invocation(prog_name: Optional[str] = None) -> bool:
    if prog_name is None:
        prog_name = sys.argv[0] if sys.argv else ""
    return bool(UNBUNDLE_PROG_PATTERN.search(prog_name))


def _is_unbundle_entrypoint(value: Optional[str] = None) -> bool:
    if value is None:
        value = globals().get("__file__", sys.argv[0] if sys.argv else "")
    toks = _invocation_tokens(value)
    return len(toks) >= 3 and toks[-3:] == ["dwimsy", "meta", "unbundle"]


VERSION_SPACE_HELP = """Version-space options (processed strictly left-to-right):
  --version=TAG                 Select TAG as the current version. May occur more than once.
  --version-list                List versions and mark the selected version.
  --version-include=SRC         Append all streams from SRC without executing foreign code.
  --version-include-primary=SRC Append only SRC primary stream.
  --version-include-alt=SRC     Append SRC alternate streams.
  --version-include-altN=SRC    Append SRC stream altN.
  --version-restrict-to=PATTERN Keep only matching versions/streams.
  --version-prune=PATTERN       Remove matching versions/streams.
  --version-splice=SPEC         Reinsert matching history with hash validation.
  --version-alt[=TAG]           Fork a new primary stream; bare form means selected.
  --version-help                Show this help.
  -a NAME / --argv0 NAME        Override invocation identity; may be interleaved with the above.

The VersionSpace transformations are applied in argv order. --version=TAG selects the
current version at that point without itself changing VersionSpace; a later --version=TAG
may replace the selection.
"""


def _tree_state_for_bundle(root: Path) -> Dict[str, bytes]:
    """Read the portable project tree in the same form used by bundle creation."""
    from dwimsy.meta.bundle import create_tree_state

    return create_tree_state(root, with_deps=True)


def bootstrap_in_memory_cli(argv: Optional[List[str]] = None) -> None:
    """Mount bundle payload and dispatch CLI across Paths A, B, and C."""
    effective_args = sys.argv[1:] if argv is None else list(argv)

    this_mod = sys.modules.get(__name__)
    if this_mod is not None and "dwimsy.meta.unbundle" not in sys.modules:
        sys.modules["dwimsy.meta.unbundle"] = this_mod
    if not any(isinstance(finder, BundleFinder) for finder in sys.meta_path):
        sys.meta_path.insert(0, BundleFinder(_get_active_blztar(), self_mod=this_mod))

    from dwimsy.meta.versions import VersionSpace

    pipeline, remaining_args = parse_early_pipeline_flags(effective_args)

    raw_argv0 = pipeline["argv0"] or (
        sys.argv[0] if sys.argv and sys.argv[0] else "dwimsy"
    )
    argv0_effective = get_invocation_path(raw_argv0)
    is_checkout, repo_root = detect_self_location(argv0_effective)

    raw_b64 = _get_active_blztar()
    vspace = VersionSpace.from_blztar(raw_b64)

    selected = vspace.resolve_selection("primary")
    for op, value in pipeline["operations"]:
        if op == "argv0":
            continue
        if op == "include":
            vspace.include_source(value)
        elif op == "include-primary":
            vspace.include_source(value, stream_filter="primary")
        elif op == "include-alt":
            vspace.include_source(value, stream_filter="alt")
        elif op == "include-altN":
            idx, src = value
            vspace.include_source(src, stream_filter=f"alt{idx}")
        elif op == "restrict_to":
            vspace.restrict_to(value)
        elif op == "prune":
            vspace.prune(value)
        elif op == "splice":
            vspace.splice(value)
        elif op == "alt":
            if value is None or value.lower() == "selected":
                vspace.branch_selection(selected)
            else:
                branch_selection = vspace.resolve_selection(value)
                if not branch_selection:
                    raise ValueError(
                        f"Version selector '{value}' could not be resolved."
                    )
                vspace.branch_selection(branch_selection)
        elif op == "version":
            if value.lower() != "selected":
                selected = vspace.resolve_selection(value)
                if not selected and value.lower() != "unbundled":
                    raise ValueError(
                        f"Version selector '{value}' could not be resolved."
                    )

    if pipeline.get("print_version"):
        is_verbose = pipeline.get("explicit_verbose_count", 0) > 0
        target_cmd = resolve_argv0_command(argv0_effective)
        prog = (
            f"dwimsy-{target_cmd[0]}"
            if target_cmd and target_cmd[0] not in ("dwimsy", "meta")
            else ("dwimsy meta" if target_cmd and target_cmd[0] == "meta" else "dwimsy")
        )
        from dwimsy.meta.integrity import version_banner

        banner = version_banner(prog=prog, verbose=is_verbose)
        print(banner)
        sys.exit(0)
    if (
        any(op == "version-help" for op, _ in pipeline["operations"])
        or pipeline.get("early_exit") == "version-help"
    ):
        print(VERSION_SPACE_HELP)
        sys.exit(0)
    if (
        any(op == "version-list" for op, _ in pipeline["operations"])
        or pipeline.get("early_exit") == "version-list"
    ):
        output = pipeline["version_list_snapshot"] or vspace.format_list_versions(
            on_disk_root=repo_root if is_checkout else None,
            selected=selected,
            verbose=pipeline.get("version_list_verbose", False),
        )
        print(output)
        sys.exit(0)
    if pipeline.get("test_mode"):
        from dwimsy.tests import run_tests

        non_flags = [
            a
            for a in remaining_args
            if not a.startswith("-") and a not in ("dwimsy", "tests", "main")
        ]
        target_cmd = resolve_argv0_command(argv0_effective)
        scoped_phrase = (
            " ".join(non_flags)
            if non_flags
            else (
                " ".join(target_cmd)
                if target_cmd and target_cmd[0] not in ("dwimsy", "tests", "main")
                else None
            )
        )
        pattern = (
            [pipeline["test_pattern"]]
            if pipeline.get("test_pattern")
            else ([scoped_phrase] if scoped_phrase else None)
        )
        test_verbose = max(
            1,
            1
            + pipeline.get("short_v_count", 0)
            + pipeline.get("explicit_verbose_count", 0),
        )
        rc = run_tests(pattern, verbose=test_verbose)
        sys.exit(rc)

    effective_blztar = vspace.to_blztar()
    ver_sel = None
    if selected and selected.first:
        if selected.is_multi:
            raise ValueError(
                "The active selection contains multiple alternate streams and cannot be used as a single execution target."
            )
        ver_sel = selected.first.version.tag

    version_selector = pipeline.get("version")
    if (
        ver_sel is None
        or (
            isinstance(version_selector, str)
            and version_selector.lower() in ("baseline", "primary")
        )
        or (
            version_selector is None
            and selected
            and selected.first
            and selected.first.stream is vspace.streams[0]
        )
    ):
        this_mod = sys.modules.get(__name__)
        sys.modules["dwimsy.meta.unbundle"] = this_mod
        sys.meta_path = [f for f in sys.meta_path if not isinstance(f, BundleFinder)]
        bundle_finder = BundleFinder(
            effective_blztar, self_mod=this_mod, on_disk_root=repo_root
        )
        sys.meta_path.insert(0, bundle_finder)

        # Preserve the effective invocation identity while discarding the
        # universal options consumed by this bootstrap.
        sys.argv = [argv0_effective] + remaining_args

        import dwimsy.cli.__main__ as cli_main

        rc = cli_main.main()
        sys.exit(rc if rc is not None else 0)

    if ver_sel.lower() == "unbundled":
        if is_checkout and repo_root:
            target_unbundle = repo_root / "dwimsy" / "meta" / "unbundle.py"
            target_b64 = ""
            if target_unbundle.is_file():
                m = _BLZTAR_RE.search(target_unbundle.read_bytes())
                if m:
                    target_b64 = target_unbundle.read_bytes()[
                        m.start("prefix") : m.end("suffix")
                    ].decode("ascii")

            if target_b64.strip() == effective_blztar.strip():
                sys.argv = [argv0_effective] + remaining_args
                import dwimsy.cli.__main__ as cli_main

                cli_main.main()
                return
            else:
                with tempfile.TemporaryDirectory() as tmpdir:
                    temp_unbundle = Path(tmpdir) / "unbundle.py"
                    template = elide_blztar_bytes(target_unbundle.read_bytes())
                    temp_unbundle.write_bytes(
                        inject_blztar_bytes(template, effective_blztar)
                    )
                    cmd = [
                        sys.executable,
                        str(temp_unbundle),
                        f"--argv0={target_unbundle}",
                    ] + remaining_args
                    res = subprocess.run(cmd, cwd=str(repo_root))
                    sys.exit(res.returncode)
        else:
            raise ValueError(
                "No unbundled on-disk version available in current environment"
            )

    res = vspace.resolve_version_ref(ver_sel)
    if res is None:
        raise ValueError(f"Version selector '{ver_sel}' could not be resolved.")

    st, ord_idx, v_ref = res
    with tempfile.TemporaryDirectory() as tmpdir:
        temp_bundle = Path(tmpdir) / f"dwimsy_{v_ref.tag}.py"
        mat_state = st.materialize_layer_state(ord_idx)
        template_bytes = elide_blztar_bytes(Path(__file__).read_bytes())

        from dwimsy.meta.versions import Stream, Layer

        clean_state = {}
        for k, v in mat_state.items():
            clean_k = (
                k[len("<dwimsy-bundle>/") :] if k.startswith("<dwimsy-bundle>/") else k
            )
            clean_state[clean_k] = v

        single_space = VersionSpace(
            [
                Stream(
                    0,
                    "primary",
                    [Layer(clean_state, is_delta=False, version_tag=v_ref.tag)],
                )
            ]
        )
        temp_bundle.write_bytes(
            inject_blztar_bytes(template_bytes, single_space.to_blztar())
        )

        cmd = [
            sys.executable,
            str(temp_bundle),
            f"--argv0={argv0_effective}",
        ] + remaining_args
        res_proc = subprocess.run(cmd)
        sys.exit(res_proc.returncode)


def main(argv: Optional[List[str]] = None) -> int:
    """CLI entrypoint for standalone unbundle script."""
    effective = sys.argv[1:] if argv is None else list(argv)
    pipeline, remaining = parse_early_pipeline_flags(effective)

    this_mod = sys.modules.get(__name__)
    if this_mod is not None and "dwimsy.meta.unbundle" not in sys.modules:
        sys.modules["dwimsy.meta.unbundle"] = this_mod
    if not any(isinstance(finder, BundleFinder) for finder in sys.meta_path):
        sys.meta_path.insert(0, BundleFinder(_get_active_blztar(), self_mod=this_mod))

    raw_argv0 = pipeline["argv0"] or (sys.argv[0] if sys.argv and sys.argv[0] else "")
    argv0_effective = get_invocation_path(raw_argv0) if raw_argv0 else ""
    is_checkout, repo_root = detect_self_location(argv0_effective)
    if is_checkout and repo_root and str(repo_root) not in sys.path:
        sys.path.insert(0, str(repo_root))

    if pipeline.get("print_version"):
        is_verbose = pipeline.get("explicit_verbose_count", 0) > 0
        from dwimsy.meta.integrity import version_banner

        banner = version_banner(prog="dwimsy", verbose=is_verbose)
        print(banner)
        return 0
    if pipeline.get("version_help") or pipeline.get("early_exit") == "version-help":
        print(VERSION_SPACE_HELP)
        return 0
    if pipeline.get("list_versions") or pipeline.get("early_exit") == "version-list":
        from dwimsy.meta.versions import VersionSpace

        raw_b64 = _get_active_blztar()
        vspace = VersionSpace.from_blztar(raw_b64)
        print(
            pipeline.get("version_list_snapshot")
            or vspace.format_list_versions(
                on_disk_root=repo_root if is_checkout else None,
                selected=pipeline.get("selected_ref"),
                verbose=pipeline.get("version_list_verbose", False),
            )
        )
        return 0
    if pipeline.get("test_mode"):
        from dwimsy.tests import run_tests

        non_flags = [
            a
            for a in remaining
            if not a.startswith("-") and a not in ("dwimsy", "tests", "main")
        ]
        target_cmd = resolve_argv0_command(argv0_effective)
        scoped_phrase = (
            " ".join(non_flags)
            if non_flags
            else (
                " ".join(target_cmd)
                if target_cmd and target_cmd[0] not in ("dwimsy", "tests", "main")
                else None
            )
        )
        pattern = (
            [pipeline["test_pattern"]]
            if pipeline.get("test_pattern")
            else ([scoped_phrase] if scoped_phrase else ["meta unbundle"])
        )
        test_verbose = max(
            1,
            1
            + pipeline.get("short_v_count", 0)
            + pipeline.get("explicit_verbose_count", 0),
        )
        return run_tests(pattern, verbose=test_verbose)

    prog_name = Path(argv0_effective or "dwimsy-meta-unbundle").name
    parser = argparse.ArgumentParser(
        prog=prog_name,
        description="Extract dwimsy standalone bundle.\nHomepage: https://github.com/f-fix/dwimsy",
    )
    parser.add_argument(
        "-V", "--version", action=_LazyVersionAction, version_fn=get_bundle_version
    )
    parser.add_argument(
        "-T",
        "--test",
        nargs="?",
        const=True,
        default=False,
        help="Run scoped self-tests",
    )
    parser.add_argument(
        "-v", "--verbose", action="count", default=0, help="Increase output verbosity"
    )
    parser.add_argument("--help-all", action="store_true", help="Show full help")
    parser.add_argument("-f", "--force", action="store_true", help="Replace conflicting files")
    parser.add_argument("--dry-run", action="store_true", help="Show what would be extracted without changing files")
    parser.add_argument("-q", "--quiet", action="store_true", help="Suppress non-error extraction output")
    parser.add_argument(
        "target_directory",
        nargs="?",
        default=None,
        help="Target directory for extraction",
    )
    parser.add_argument("--deps", "-d", action="store_true", help="Also extract deps/")
    args = parser.parse_args(remaining)

    if args.test is not False:
        pattern = [args.test] if isinstance(args.test, str) else ["meta unbundle"]
        this_mod = sys.modules.get(__name__)
        if this_mod is not None and "dwimsy.meta.unbundle" not in sys.modules:
            sys.modules["dwimsy.meta.unbundle"] = this_mod
        if not any(isinstance(finder, BundleFinder) for finder in sys.meta_path):
            bundle_finder = BundleFinder(_get_active_blztar(), self_mod=this_mod)
            sys.meta_path.insert(0, bundle_finder)
        from dwimsy.tests import run_tests

        return run_tests(pattern, verbose=max(args.verbose, 1))

    if not args.target_directory:
        parser.print_help(sys.stderr)
        return 1

    target_ver = pipeline.get("version")
    is_verbose = (
        getattr(args, "verbose", 0) > 0 or pipeline.get("explicit_verbose_count", 0) > 0
    )
    try:
        safe_unbundle(
            b64_string=_get_active_blztar(),
            output_dir=args.target_directory,
            with_deps=args.deps,
            force=args.force,
            dry_run=args.dry_run,
            quiet=args.quiet,
            target_version=target_ver,
            verbose=is_verbose,
        )
    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    pipeline, remaining = parse_early_pipeline_flags(sys.argv[1:])
    raw_argv0 = pipeline["argv0"] or (sys.argv[0] if sys.argv and sys.argv[0] else "")
    argv0_effective = get_invocation_path(raw_argv0) if raw_argv0 else ""
    if _is_unbundle_entrypoint(argv0_effective):
        sys.exit(main())
    else:
        bootstrap_in_memory_cli()
